import {generateTrack,randomSeed,GENERATOR_STYLES} from './generator.js?v=20261006-surfaces';
import {buildGeometry} from './engine.js?v=20261006-surfaces';
const $=s=>document.querySelector(s);
export function mountGenerator(api){
  const panel=$('.starter-section'),newButton=$('#new-btn');panel.classList.add('generator-panel');panel.innerHTML=`<div class="section-heading"><span class="section-num">IDEA</span><h2>A little inspiration</h2><span class="scene-tag">GENERATOR</span></div><p class="field-hint">Create a fresh circuit. Every seed has its own shape.</p><div id="random-track-preview" class="random-track-preview"></div><label class="studio-field">Layout character<select id="generator-style">${Object.entries(GENERATOR_STYLES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><div class="studio-fields"><label class="studio-field">Target length · meters<input id="generator-length" type="number" min="300" max="5000" step="100" value="900"></label><label class="studio-field">Control points<input id="generator-complexity" type="number" min="8" max="24" value="12"></label></div><label class="studio-field">Seed<input id="generator-seed" maxlength="32" spellcheck="false"></label><div class="generator-actions"><button id="shuffle-track" class="outline-button">↻ New idea</button><button id="apply-generated-track" class="complete-button">Use this circuit</button></div><p id="generator-summary" class="field-hint"></p>`;
  panel.append(newButton);let candidate=null;
  function preview(fresh=false){if(fresh)$('#generator-seed').value=randomSeed();const length=Number($('#generator-length').value),complexity=Number($('#generator-complexity').value);if(length<300||length>5000||!Number.isFinite(length)||complexity<8||complexity>24||!Number.isFinite(complexity)){candidate=null;$('#generator-summary').textContent='Choose 300–5,000 meters and 8–24 control points.';$('#apply-generated-track').disabled=true;return;}candidate=generateTrack({seed:$('#generator-seed').value,style:$('#generator-style').value,length,complexity,width:api.getTrack().width});$('#generator-seed').value=candidate.generator.seed;const g=buildGeometry(candidate.points,true);$('#random-track-preview').innerHTML=`<svg viewBox="65 75 870 590" role="img" aria-label="Random track preview"><path d="M${g.samples.map(p=>`${p.x.toFixed(2)} ${p.y.toFixed(2)}`).join('L')}Z" fill="none" stroke="#819b73" stroke-width="24"/><path d="M${g.samples.map(p=>`${p.x.toFixed(2)} ${p.y.toFixed(2)}`).join('L')}Z" fill="none" stroke="#344d43" stroke-width="16" stroke-linejoin="round"/></svg>`;$('#generator-summary').textContent=`${Math.round(g.length*candidate.scale).toLocaleString()} m · ${candidate.points.length} editable points · seed ${candidate.generator.seed}`;$('#apply-generated-track').disabled=false;}
  $('#shuffle-track').onclick=()=>preview(true);['style','length','complexity','seed'].forEach(id=>$('#generator-'+id).onchange=()=>preview());$('#apply-generated-track').onclick=()=>{if(candidate)api.useGenerated(candidate);};
  const saved=api.getTrack().generator;if(saved){for(const key of ['style','length','complexity','seed'])if(saved[key]!=null)$('#generator-'+key).value=saved[key];}else $('#generator-seed').value=randomSeed();preview();return {refresh(){}};
}
